panel=[]
for t in rows:
    (c,canon,cid,key,cl,sub,cat,foods,rank,orac,b1,conf,ready,mg,etype,pop,eref,m1,m2,sec,strength,human,direct,safety,proox)=t
    mw={'Epicatechin':290.27,'Quercetin':302.23,'EGCG':458.37,'Genistein':270.24,'Naringenin':272.25,'Caffeic acid':180.16,'Ferulic acid':194.18,'Chlorogenic acid':354.31,'Gallic acid':170.12,'L-Ascorbic acid':176.12,'alpha-Tocopherol':430.71,'gamma-Tocopherol':416.69,'beta-Carotene':536.87,'Lycopene':536.87,'Lutein':568.87,'Zeaxanthin':568.87,'Sulforaphane':177.29,'Allicin':162.27,'Sesamol':138.12,'Eugenol':164.20}[c]
